export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  const scene = new BABYLON.Scene(engine);
  scene.clearColor = BABYLON.Color4.FromHexString("#B8B698FF");
  scene.useRightHandedSystem = true;

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(-0.35, 0.47, 0.32));
  camera.alpha = 2.261;
  camera.beta = 0.933;
  camera.radius = 1.91;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  camera.zoomToMouseLocation = true;
  camera.attachControl(canvas, true);

  var defaultPipeline = new BABYLON.DefaultRenderingPipeline("DRPP", true, scene, [camera]);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 2;

  var dirLight = new BABYLON.DirectionalLight("dirLight", new BABYLON.Vector3(-1, -1, -0.5), scene);
  dirLight.position = new BABYLON.Vector3(1, 1, 0.5);
  dirLight.shadowMaxZ = 300;

  let shadowGenerator_D = new BABYLON.CascadedShadowGenerator(1024, dirLight);
  shadowGenerator_D.autoCalcDepthBounds = true;
  shadowGenerator_D.lambda = 1;
  shadowGenerator_D.bias = 0.001;
  shadowGenerator_D._darkness = -3.0;

  dirLight.getShadowGenerator().getShadowMap().resize(1024);
  dirLight.getShadowGenerator().getShadowMap().scale(Math.pow(2, 2));

  let rootMesh;

  const edgeDetectionPP = new BABYLON.EdgeDetectionPostProcess("Edge PP", scene, 1, camera);
  edgeDetectionPP.samples = 4;
  edgeDetectionPP.edgeIntensity = 0.3;
  edgeDetectionPP.edgeWidth = 0.2;
  edgeDetectionPP.edgeColor = new BABYLON.Color3(0, 0, 0);

  engine.setHardwareScalingLevel(0.66);

  var advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");

  BABYLON.SceneLoader.ImportMeshAsync("", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", "stylized kitchen.glb").then((result) => {
    rootMesh = result.meshes[0];
    rootMesh.normalizeToUnitCube(true);

    camera.setTarget(rootMesh.position.subtract(new BABYLON.Vector3(0, 0.1, 0)));

    scene.meshes.forEach((m) => {
      m.alwaysSelectAsActiveMesh = true;
      m.receiveShadows = true;
      shadowGenerator_D.addShadowCaster(m);

      if (m.material) {
        m.material.unlit = false;
        m.material.transparencyMode = 0;
      }
    });

    let dish = rootMesh.getChildTransformNodes().find((node) => node.name === "Dish");
    if (dish) {
      dish.parent = null;
    } else {
      dish = rootMesh.getChildTransformNodes().find((node) => node.name === "cup.004");
      dish.parent = null;
      dish.scaling.scaleInPlace(0.1);

      camera.alpha = 0.759;
      camera.beta = 1.33;
      camera.radius = 1.5;

      dirLight.direction = new BABYLON.Vector3(0.07, -0.88, -0.47);
      light.intensity = 1;

      var rect1 = new BABYLON.GUI.Rectangle("Cup Rect");
      rect1.width = 0.2;
      rect1.height = "60px";
      rect1.width = "240px";
      rect1.cornerRadius = 12;
      rect1.color = "Orange";
      rect1.thickness = 4;
      rect1.background = "black";
      advancedTexture.addControl(rect1);
      rect1.linkWithMesh(dish);
      rect1.linkOffsetY = -100;

      var label = new BABYLON.GUI.TextBlock("Cup UI");
      label.text = "Place me!";
      label.fontSize = "30";
      label.resizeToFit = true;
      rect1.addControl(label);
    }

    defaultPipeline.fxaaEnabled = true;
    defaultPipeline.samples = 4;

    function onPointerMove(evt) {
      var pickInfo = scene.pick(
        scene.pointerX,
        scene.pointerY,
        (mesh) => {
          return !mesh.isDescendantOf(dish);
        },
        false,
        camera
      );

      if (pickInfo.hit) {
        if (dish) {
          dish.position = pickInfo.pickedPoint;

          var axis1 = pickInfo.getNormal();
          var axis2 = BABYLON.Vector3.Up();
          var axis3 = BABYLON.Vector3.Up();
          var start = new BABYLON.Vector3(Math.PI / 2, 0, 0);

          BABYLON.Vector3.CrossToRef(start, axis1, axis2);
          BABYLON.Vector3.CrossToRef(axis2, axis1, axis3);
          var tmpVec = BABYLON.Vector3.RotationFromAxis(axis3.negate(), axis1, axis2);
          var quat = BABYLON.Quaternion.RotationYawPitchRoll(tmpVec.y, tmpVec.x, tmpVec.z);
          if (pickInfo.pickedMesh.rotationQuaternion) {
            dish.rotationQuaternion = pickInfo.pickedMesh.rotationQuaternion.multiply(quat);
          } else dish.rotationQuaternion = quat;
        }
      }
    }

    canvas.addEventListener("pointermove", onPointerMove, false);

    scene.onDispose = function () {
      canvas.removeEventListener("pointermove", onPointerMove);
    };
  });

  return scene;
}
